const test = require('node:test');
const assert = require('node:assert');
const { createUser, ValidationError } = require('../users');

test('creates a user', () => {
  assert.deepStrictEqual(createUser({ name: 'Asha', age: 31 }), { name: 'Asha', age: 31 });
});

test('accepts numeric string ages and returns a number', () => {
  assert.deepStrictEqual(createUser({ name: 'Asha', age: '42' }), { name: 'Asha', age: 42 });
});

test('trims the name', () => {
  assert.deepStrictEqual(createUser({ name: '  Asha ', age: 1 }), { name: 'Asha', age: 1 });
});

test('accepts boundary ages 0 and 150', () => {
  assert.strictEqual(createUser({ name: 'A', age: 0 }).age, 0);
  assert.strictEqual(createUser({ name: 'A', age: '150' }).age, 150);
});

test('rejects invalid names', () => {
  for (const name of ['', '   ', null, undefined, 42, ['Asha']]) {
    assert.throws(() => createUser({ name, age: 30 }), ValidationError, `name: ${String(name)}`);
  }
});

test('rejects invalid ages', () => {
  const bad = [-1, 151, 4.5, NaN, Infinity, '', '  ', '4.5', '-3', '1e2', '0x1F', 'abc', '151', null, undefined, true, [30]];
  for (const age of bad) {
    assert.throws(() => createUser({ name: 'Asha', age }), ValidationError, `age: ${String(age)}`);
  }
});

test('rejects non-object input', () => {
  for (const input of [null, undefined, 'Asha', 42]) {
    assert.throws(() => createUser(input), ValidationError);
  }
});

